// URL Shortener — core encode/decode logic
const BASE62 = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

function encodeBase62(num) {
  if (num === 0) return BASE62[0];
  let result = '';
  while (num > 0) {
    result = BASE62[num % 62] + result;
    num = Math.floor(num / 62);
  }
  return result.padStart(6, BASE62[0]); // always 6 chars
}

function decodeBase62(str) {
  return str.split('').reduce((acc, ch) => acc * 62 + BASE62.indexOf(ch), 0);
}

// Shorten: assign a unique auto-increment ID → encode
async function shortenUrl(longUrl, db, cache) {
  const existing = await db.query(
    'SELECT code FROM url_mappings WHERE long_url = $1 LIMIT 1', [longUrl]
  );
  if (existing.rows[0]) return existing.rows[0].code; // deduplicate

  const { rows } = await db.query(
    'INSERT INTO url_mappings (long_url) VALUES ($1) RETURNING id', [longUrl]
  );
  const code = encodeBase62(rows[0].id);
  await db.query('UPDATE url_mappings SET code = $1 WHERE id = $2', [code, rows[0].id]);
  await cache.set(code, longUrl, { EX: 86400 }); // warm the cache
  return code;
}

// Redirect: cache-first lookup
async function resolveCode(code, db, cache) {
  const cached = await cache.get(code);
  if (cached) return cached; // ~1ms Redis hit

  const { rows } = await db.query(
    'SELECT long_url, expires_at FROM url_mappings WHERE code = $1', [code]
  );
  if (!rows[0]) return null;
  if (rows[0].expires_at && rows[0].expires_at < new Date()) return null; // expired

  await cache.set(code, rows[0].long_url, { EX: 3600 }); // backfill cache
  return rows[0].long_url;
}

// News Feed — fan-out on write (push model)
// Called when any user publishes a post
async function fanOutPost(authorId, postId, redis, db) {
  // Get all follower IDs (paginated for large accounts)
  const { rows } = await db.query(
    'SELECT follower_id FROM follows WHERE followee_id = $1', [authorId]
  );

  const timestamp = Date.now();
  const pipeline = redis.pipeline();

  for (const { follower_id } of rows) {
    // ZADD feed:{userId} score member — sorted set by timestamp
    pipeline.zadd(`feed:${follower_id}`, timestamp, postId);
    // Trim feed to last 1000 posts to bound memory
    pipeline.zremrangebyrank(`feed:${follower_id}`, 0, -1001);
  }
  await pipeline.exec();
}

